SELECT id, reference_signal_id, evaluation_path, evaluated_at, five_minute_signal_id, five_minute_raw_decision, five_minute_effective_decision, one_hour_signal_id, one_hour_effective_decision, assessment_band, final_result, created_at FROM buy_htf_assessment_audit WHERE reference_signal_id IN (159285,159407,159408,165412,165415) OR evaluated_at BETWEEN '2026-10-11 22:39:55' AND '2026-10-11 22:40:05' OR evaluated_at BETWEEN '2026-10-12 02:34:55' AND '2026-10-12 02:35:05' ORDER BY evaluated_at LIMIT 50